def finding(item, n, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(n + 5) % len(KINDS)], KINDS[(n + 13) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as governed pipeline-definition context while deployment, scheduler, run, dataset, lineage-event, secret, telemetry and records masters remain external.",
            "source_refs": refs,
            "questions": [
              {"id": f"{fid}-q01", "text": f"What stable identity, pipeline version, typed value and explicit unknown establish {low}?", "kind": kinds[0], "answer_data": ["pipeline, component and external master identifiers", "typed value, unit, schema or policy profile", "unknown, unavailable, disputed and not-applicable states"]},
              {"id": f"{fid}-q02", "text": f"Who declared, owns, approves, operates, observes or may rely on {low}, under which authority and limits?", "kind": kinds[1], "answer_data": ["actor, agent, role, organization and contact", "authority, purpose, policy and access scope", "conflict, exception, escalation and accountability"]},
              {"id": f"{fid}-q03", "text": f"Which effective, release, deployment, scheduled, event, recorded, ingested and knowledge times, evidence and uncertainty qualify {low}?", "kind": kinds[2], "answer_data": ["distinct definition, release and runtime times", "source, evidence, method, confidence and uncertainty", "successor, correction, retention and audit"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed pipeline-definition data for {low}, qualified by version, source, authority, time, evidence and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned pipeline evidence for {low}.", "media_or_form": ["logical pipeline-definition assertion", "topology, contract, policy, release, mapping or audit record"], "serial": True, "identity_strategy": f"Pipeline ID plus independent component, contract, policy, release or artifact ID for {fid}; name, path, date, URL and digest never identify the pipeline alone.", "source_refs": refs}],
            "inline_only_rationale": None}

def structure():
    bundles = []
    n = 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            findings = []
            for item in items:
                n += 1
                findings.append(finding(item, n, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups governed pipeline context for {lname.lower()}.", "source_refs": refs, "findings": findings})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed pipeline context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({r for layer in layers for r in layer[2]}), "layers": rendered})
    return {"bundles": bundles}

